 function weekReport() {
  const line = i => {
   const k = i.kind === 'task' ? '업무' : i.kind === 'event' ? '일정' : '전할 말';
   const parts = [`[${k}] ${i.title}`];
   if (i.kind === 'task') parts.push(statuses[i.status], i.progress ? `진행 ${i.progress}%` : '', i.due ? `마감 ${shortDate(i.due)} (${dDay(i.due).label})` : '마감 미정', `담당 ${personName(i.assignee)}`, priorityLabel(i) !== '보통' ? priorityLabel(i) : '', i.collab === 'requested' ? '협업 요청 중' : '', confirmPending.has(i.id) ? '확인 요청 중' : '');
   else if (i.kind === 'event') parts.splice(0, 1, `[일정] ${shortDate(i.day)} ${timeRangeLabel(i)} ${displayTitle(i, me.id)} · ${personName(i.assignee)}`);
   else if (i.ack) parts.push(ACK_MODES[ackMode(i)]);
   parts.push(`작성 ${authorLabel(i)}`);
   const firstLink = (i.links || [])[0];
   if (firstLink) parts.push(firstLink.url);
   return '- ' + parts.filter(Boolean).join(' · ');
  };
  const byTopic = list => [...topics, {id: '', name: TOPIC_NONE}].map(t => ({t, rows: list.filter(i => (i.topic_id || '') === t.id)})).filter(g => g.rows.length).map(g => `### ${g.t.name} (${g.rows.length})\n${g.rows.map(line).join('\n')}`).join('\n\n');
  const names = ['월', '화', '수', '목', '금', '토', '일'];
  const days = Array.from({length: 7}, (_, i) => offsetDate(weekStart, i));
  const state = SEATS.map(s => {
   const rows = days.map((d, i) => { const c = checkins.find(x => x.seat === s.key && x.day === d); if (!c) return null; const r = reactions.find(x => x.id === `${s.key}__${d}`); return `  - ${names[i]} ${shortDate(d)}: ${LOADS[c.load] || '-'} → ${MOODS[c.mood] || '-'} → ${c.ask && c.ask !== 'none' ? ASKS[c.ask] : '바라는 것 없음'}${c.message ? ` · "${c.message}"` : ''}${r ? ` · 답: ${r.by_name} ${REACTIONS[r.kind]}` : ''}`; }).filter(Boolean);
   return `- ${s.name}${rows.length ? '\n' + rows.join('\n') : ': 남긴 기록 없음'}`;
  }).join('\n');
  const upd = weekUpdates.map(c => { const it = items.find(i => i.id === c.item_id) || {}; return `- ${timeLabel(c.created_at)} ${personName(c.author_name)} · ${it.title || '(삭제된 항목)'}: ${c.body.replace(/\s*\n\s*/g, ' / ')}`; }).join('\n');
  const next = [...nextWeekJoint, ...nextWeekTasks].map(line).join('\n');
  return [
   `# Pocket Sync 주간 회의 · ${weekStart.slice(0, 4)}년 ${shortDate(weekStart)} — ${shortDate(weekEnd)}`,
   `카테고리: ${topicFilter === 'all' ? TOPIC_ALL : topicName(topicFilter)} · 작성 ${fullTime(nowIso())} · 기록 ${weekItems.length}건 · 업데이트 ${weekUpdates.length}건 · 현재 미완료 업무 ${pendingTasks.length}건`,
   '', '## 이번 주 우리 상태 (일의 양 → 마음 → 바라는 것)', state,
   '', `## 회의에서 먼저 확인할 일 (${meetingChecks.length})`, `미확인 긴급 ${urgentForMeeting.length}건 · 기한 지난 미완료 업무 ${lateTasks.length}건 · 아주급함 업무 ${criticalTasks.length}건`, meetingChecks.length ? meetingChecks.map(line).join('\n') : '- 없음',
   '', `## 이번 주 공유한 기록 (${weekItems.length})`, weekItems.length ? byTopic(weekItems) : '- 없음',
   '', `## 이번 주 업데이트 (${weekUpdates.length})`, upd || '- 없음',
   '', `## 다음 주 예정 (${nextWeekJoint.length + nextWeekTasks.length}) · ${shortDate(nextWeekStart)} — ${shortDate(nextWeekEnd)}`, next || '- 없음',
   '', '## 회의에서 정한 것 / 다음 행동', '- ', ''
  ].join('\n');
 }
 async function copyReport() {
  const text = weekReport();
  try { await navigator.clipboard.writeText(text); toast.success('회의록을 복사했어요. 카카오톡이나 슬랙에 붙여넣기 하세요.'); return; } catch {}
  try { const ta = document.createElement('textarea'); ta.value = text; ta.setAttribute('readonly', ''); ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0'; document.body.appendChild(ta); ta.select(); const ok = document.execCommand('copy'); ta.remove(); if (!ok) throw new Error('copy'); toast.success('회의록을 복사했어요.'); }
  catch { toast.error('복사가 막혀 있어요. md 파일로 저장해 주세요.'); }
 }
 function fallbackDownload(text, filename) {
  try { const blob = new Blob([text], {type: 'text/markdown;charset=utf-8'}); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 5000); toast.info('브라우저 다운로드로 저장을 요청했어요.'); }
  catch { toast.error('파일 저장이 막혀 있어요. 텍스트 복사를 이용해 주세요.'); }
 }
 async function downloadReport() {
  const text = weekReport(), filename = `pocket-sync-weekly-${weekStart}.md`;
  let dl = null;
  try { dl = window.claude && typeof window.claude.use === 'function' ? await window.claude.use('downloads') : null; } catch { dl = null; }
  if (!dl) { fallbackDownload(text, filename); return; }
  try { await dl.save({filename, data: text}); toast.success('md 파일로 저장했어요.'); }
  catch (e) { const code = e && e.code; if (code === 'declined') return; if (code === 'rate_limited') { toast.error('저장 창이 이미 열려 있어요. 잠시 후 다시 눌러 주세요.'); return; } fallbackDownload(text, filename); }
 }
 async function importRecords() {
  const input = document.createElement('input'); input.type = 'file'; input.accept = '.json,application/json';
  input.onchange = async () => {
   const file = input.files && input.files[0]; if (!file) return;
   let dump; try { dump = JSON.parse(await file.text()); } catch { toast.error('파일을 읽을 수 없어요. 받은 JSON 파일을 그대로 골라 주세요.'); return; }
   const db = dbRef.current; if (!db) return;
   let added = 0, skipped = 0;
   setBusy(true);
   try {
    for (const col of COLLECTIONS) {
     if (col === 'members' || !dump[col]) continue;
     for (const [id, doc] of Object.entries(dump[col])) {
      const ref = db.doc(col + '/' + id), cur = await ref.get();
      if (cur.exists) { skipped++; continue; }
      await ref.set(doc); added++;
     }
    }
    toast.success(`기존 기록 ${added}건을 가져왔어요.${skipped ? ` 이미 있는 ${skipped}건은 건너뛰었어요.` : ''}`);
   } catch (e) { toast.error(friendlyError(e)); } finally { setBusy(false); }
  };
  input.click();
 }
