function InlinePopover({popover, items, topics, myName, busy, onClose, onPatch, onNewTopic}) {
 const ref = useRef(null);
 useEscape(true, onClose);
 useEffect(() => {
  const down = e => { if (ref.current && !ref.current.contains(e.target)) onClose(); };
  const dismiss = () => onClose();
  const timer = setTimeout(() => { document.addEventListener('pointerdown', down); window.addEventListener('resize', dismiss); window.addEventListener('scroll', dismiss, true); }, 0);
  return () => { clearTimeout(timer); document.removeEventListener('pointerdown', down); window.removeEventListener('resize', dismiss); window.removeEventListener('scroll', dismiss, true); };
 }, [onClose]);
 const item = items.find(i => i.id === popover.itemId); if (!item) return null;
 const kind = popover.kind;
 const options = kind === 'rank' ? [{value: 0, label: '– 정하지 않음 (마감·중요도 순)'}, ...Array.from({length: Math.min(10, (popover.meta && popover.meta.count) || 5)}, (_, k) => ({value: k + 1, label: `${k + 1}순위`}))] : kind === 'progress' ? [0, 25, 50, 75, 100].map(v => ({value: v, label: v === 100 ? '100% · 완료' : `${v}%`})) : kind === 'due' ? [{value: '', label: '없음'}, {value: today(), label: '오늘'}, {value: offsetDate(today(), 1), label: '내일'}, {value: nextFriday(), label: `금 ${shortDate(nextFriday())}`}]
  : kind === 'status' ? Object.entries(statuses).map(([value, label]) => ({value, label, tag: value}))
  : kind === 'topic' ? [...topics.map(t => ({value: t.id, label: t.name})), {value: '', label: TOPIC_NONE}]
  : kind === 'priority' ? (item.kind === 'daily' ? Object.entries(ACK_MODES).map(([value, label]) => ({value, label, tag: value === 'none' ? 'normal' : value === 'share' ? 'ask' : value})) : Object.entries(taskPriorities).map(([value, label]) => ({value, label, tag: value === 'share' ? 'normal' : value})))
  : kind === 'kind' ? Object.entries(KINDS).map(([value, label]) => ({value, label, tag: value === 'task' ? 'todo' : value}))
  : [...SEATS.map(s => ({value: s.name, label: s.name, me: s.name === myName})).sort((a, b) => Number(!!b.me) - Number(!!a.me)), {value: '함께', label: '함께'}];
 const current = kind === 'rank' ? (item.prio_no || 0) : kind === 'progress' ? item.progress : kind === 'due' ? item.due : kind === 'status' ? item.status : kind === 'topic' ? (item.topic_id || '') : kind === 'priority' ? (item.kind === 'daily' ? ackMode(item) : item.priority) : kind === 'kind' ? item.kind : personName(item.assignee);
 const title = kind === 'rank' ? '우선순위 정하기' : kind === 'progress' ? '진행률 바꾸기' : kind === 'due' ? '마감일 바꾸기' : kind === 'status' ? '진행 상태 바꾸기' : kind === 'topic' ? (item.topic_id ? '카테고리 바꾸기' : '카테고리 정하기') : kind === 'priority' ? (item.kind === 'daily' ? '상대 확인 바꾸기' : '중요도 바꾸기') : kind === 'kind' ? '종류 바꾸기' : item.kind === 'event' ? '함께할 사람 바꾸기' : '담당 바꾸기';
 const patch = value => onPatch(item, kind === 'rank' ? {prio_no: value} : kind === 'progress' ? progressFields(item, value) : kind === 'due' ? {due: value} : kind === 'status' ? {status: value} : kind === 'topic' ? {topic_id: value} : kind === 'priority' ? (item.kind === 'daily' ? fromAckMode(value) : {priority: value}) : kind === 'kind' ? {kind: value} : {assignee: value}, popover.origin);
 const width = kind === 'topic' ? 236 : 208, est = Math.min(window.innerHeight - 16, 40 + options.length * 37 + (kind === 'due' || kind === 'topic' ? 46 : 0));
 const left = Math.max(8, Math.min(popover.left, window.innerWidth - width - 8));
 let top = popover.bottom + 6; if (top + est > window.innerHeight - 8) top = Math.max(8, popover.top - est - 6);
 return html`<div class="popover-layer"><div class="popover" ref=${ref} role="menu" aria-label=${title} style=${`left:${left}px;top:${top}px;width:${width}px`}><div class="popover-title">${title} · ${item.title}</div>${options.map(o => html`<button type="button" role="menuitemradio" key=${o.value} aria-checked=${current === o.value} class=${cx('option', current === o.value && 'current')} disabled=${busy} onClick=${() => patch(o.value)}>${o.tag ? html`<span class=${'tag ' + o.tag}>${o.label}</span>` : o.label}${o.me && html`<em class="you-tag">나</em>`}${current === o.value && I('Check', 14)}</button>`)}${kind === 'due' && html`<label class="popover-date">${I('CalendarDays', 14)}<input type="date" aria-label="날짜 직접 선택" value=${item.due} disabled=${busy} onChange=${e => { if (e.target.value) patch(e.target.value); }} /></label>`}${kind === 'topic' && html`<button type="button" class="option popover-new" disabled=${busy} onClick=${() => onNewTopic(item)}>${I('Plus', 14)}새 카테고리 만들어 지정</button>`}</div></div>`;
}

