   <section class="thread-events"><div class="section-heading"><h2>이 날 일정 <span class="count">${sorted.length}</span></h2></div>${sorted.length ? sorted.map(e => { const masked = isMasked(e, meId), cc = comments.filter(c => c.item_id === e.id).length; return html`<button type="button" key=${e.id} class=${cx('thread-ev', masked && 'private')} onClick=${() => onOpen(e.id)}><span class="wk-time">${e.start ? `${e.start}–${e.end}` : '종일'}</span><span class="wk-title">${masked && I('Lock', 12)}<span>${displayTitle(e, meId)}</span>${personName(e.assignee) === '함께' && html`<span class="tag joint">함께</span>`}<${CollabTag} item=${e} meId=${meId} /></span>${cc > 0 && html`<span class="wk-cc">${I('MessageCircle', 11)}${cc}</span>`}${I('ChevronRight', 14)}</button>`; }) : html`<p class="side-empty">이 날 적힌 일정이 없어요.</p>`}<p class="section-help">일정 하나에 대한 이야기는 그 일정을 열어 댓글로 남겨요.</p></section>
