function FeedPanel({anchor, events, isFresh, freshCount, onOpenItem, onOpenDay, onOpenThread, onMarkAll, onClose}) {
 const ref = useRef(null);
 useEscape(true, onClose);
 useEffect(() => { const down = e => { if (ref.current && !ref.current.contains(e.target)) onClose(); }; const t = setTimeout(() => { document.addEventListener('pointerdown', down); window.addEventListener('resize', onClose); }, 0); return () => { clearTimeout(t); document.removeEventListener('pointerdown', down); window.removeEventListener('resize', onClose); }; }, [onClose]);
 const width = Math.min(390, window.innerWidth - 16), left = Math.max(8, Math.min(anchor.left - width, window.innerWidth - width - 8));
 const fresh = events.filter(isFresh), past = events.filter(e => !isFresh(e)).slice(0, 12);
 const created = it => it.kind === 'task' ? (personName(it.assignee) === '함께' ? '함께 할 업무 추가' : isMyTaskName(it) ? '나에게 업무 요청' : '업무 추가') : it.kind === 'event' ? '일정 추가' : it.ack ? `${ACK_MODES[ackMode(it)]} 보냄` : '전할 말 남김';
 const verb = e => e.type === 'daynote' ? `${e.target === '내' ? '내' : e.target} ${shortDate(e.thread.day)} 일정에 한마디` : e.type === 'created' ? created(e.item) : e.type === 'updated' ? e.text : e.type === 'comment' ? '업데이트 남김' : e.type === 'ack' ? '확인했어요' : e.type === 'reaction' ? '내 오늘의 나에 답함' : '오늘의 나 남김';
 const row = e => html`<button type="button" key=${e.key} class=${cx('feed-row', isFresh(e) && 'fresh', e.type)} onClick=${() => (e.item ? onOpenItem(e.item.id) : e.thread && onOpenThread ? onOpenThread(e.thread) : onOpenDay(e.day))}><span class=${cx('avatar mini', e.who === '권중선' && 'amber')}>${(e.who || '?').slice(0, 1)}</span><span class="feed-body"><span class="feed-line"><strong>${e.who}</strong><em>${verb(e)}</em></span>${e.item && html`<span class="feed-title">${e.item.title}</span>`}${(e.type === 'comment' || e.type === 'reaction' || e.type === 'checkin' || e.type === 'daynote') && e.text && html`<span class="feed-text">${e.text}</span>`}${e.type === 'updated' && e.item.kind === 'event' && e.text.startsWith('협업') && (e.item.collab === 'requested' ? e.item.collab_note : e.item.collab_reply) && html`<span class="feed-text">“${e.item.collab === 'requested' ? e.item.collab_note : e.item.collab_reply}”</span>`}</span><span class="feed-time"><${Stamp} at=${e.at} /></span></button>`;
 return html`<div class="popover-layer"><div class="popover feed-panel" ref=${ref} role="dialog" aria-label="새 소식" style=${`left:${left}px;top:${anchor.top + 8}px;width:${width}px`}>
  <div class="feed-head"><div><strong>새 소식</strong><small>${freshCount ? `마지막으로 본 뒤 ${freshCount}건` : '모두 확인했어요'}</small></div>${freshCount > 0 && html`<button type="button" class="text-button" onClick=${onMarkAll}>${I('CheckCheck', 14)}모두 확인</button>`}</div>
  <div class="feed-list">${fresh.length ? fresh.map(row) : html`<p class="feed-empty">상대가 새로 남기거나 바꾼 것이 없어요.</p>`}${past.length > 0 && html`<div class="feed-sub">지난 소식</div>`}${past.map(row)}</div>
  <p class="feed-foot">항목을 열면 그 항목의 점 표시가 사라져요.</p>
 </div></div>`;
}
const isMyTaskName = item => { const me = (window.__psMe || {}).name; return !!me && isMyTask(item, me); };

/* ---------- Search ---------- */
function SearchDialog({items, comments, topicName, meId, initialPinned, archiveState, onLoadArchive, onOpen, onClose}) {
 const [q, setQ] = useState(''), [pinnedOnly, setPinnedOnly] = useState(!!initialPinned), [kind, setKind] = useState('all');
 const tokens = q.trim().toLowerCase().split(/\s+/).filter(Boolean);
 const byItem = useMemo(() => { const m = new Map(); for (const c of comments) { const t = c.body + ' ' + (c.links || []).map(l => (l.label || '') + ' ' + l.url).join(' '); m.set(c.item_id, (m.get(c.item_id) || '') + ' \n ' + t); } return m; }, [comments]);
 const textOf = i => [i.title, i.body, personName(i.assignee), i.author_name, ...(i.links || []).map(l => (l.label || '') + ' ' + l.url), byItem.get(i.id) || ''].join(' \n ').toLowerCase();
 const active = tokens.length > 0 || pinnedOnly;
 const results = active ? items.filter(i => !isMasked(i, meId) && !i.demo && (!pinnedOnly || i.pinned) && (kind === 'all' || i.kind === kind)).filter(i => { const t = textOf(i); return tokens.every(k => t.includes(k)); }).slice(0, 80) : [];
 const snippet = i => {
  if (!tokens.length) return (i.body || '').split('\n')[0];
  const hay = [i.body, ...(byItem.get(i.id) || '').split(' \n ')].find(t => t && tokens.some(k => t.toLowerCase().includes(k))) || '';
  const low = hay.toLowerCase(), hit = tokens.find(k => low.includes(k)), idx = hit ? low.indexOf(hit) : 0;
  return (idx > 30 ? '…' + hay.slice(idx - 24, idx + 90) : hay.slice(0, 110)).replace(/\s+/g, ' ');
 };
 return html`<${Dialog} class="search-dialog" title="검색" description="제목, 내용, 업데이트, 링크, 담당자 이름에서 찾아요. 단어를 여러 개 넣으면 모두 들어간 기록만 보여요." onClose=${onClose}>
  <div class="search-box">${I('Search', 17)}<input ref=${focusOnMount} type="search" placeholder="찾을 단어" value=${q} onInput=${e => setQ(e.target.value)} aria-label="검색어" /></div>
  <div class="search-filters">${[['all', '전체'], ['task', '업무'], ['daily', '전할 말'], ['event', '일정']].map(([k, l]) => html`<button type="button" key=${k} class="chip" aria-pressed=${kind === k} onClick=${() => setKind(k)}>${l}</button>`)}<button type="button" class="chip" aria-pressed=${pinnedOnly} onClick=${() => setPinnedOnly(v => !v)}>${I('Pin', 12)}보관한 것만</button></div>
  <div class="search-results">${!active ? html`<p class="search-hint">찾을 단어를 입력하세요. 보드 어디서나 / 키를 누르면 바로 열려요.</p>` : results.length ? results.map(i => html`<button type="button" key=${i.id} class="search-row" onClick=${() => onOpen(i.id)}><${KindIcon} item=${i} /><span class="search-main"><strong>${i.pinned && html`<span class="pin-mark">${I('Pin', 12)}</span>`}${i.title}</strong>${snippet(i) && html`<small>${snippet(i)}</small>`}</span><span class="search-meta"><span>${topicName(i.topic_id)}</span><span>${shortDate(i.day)} · ${authorLabel(i)}</span></span></button>`) : html`<p class="search-hint">찾는 기록이 없어요.</p>`}${results.length === 80 && html`<p class="search-hint">결과가 많아요. 단어를 더 넣어 좁혀 보세요.</p>`}</div>
  ${PLATFORM === 'firebase' && html`<p class="search-foot">${archiveState === 'done' ? '이전 기록까지 모두 찾았어요.' : html`<${Fragment}><span>최근 ${WINDOW_DAYS}일 기록, 진행 중 업무, 보관한 인사이트에서 찾았어요.</span><button type="button" class="text-button" disabled=${archiveState === 'loading'} onClick=${onLoadArchive}>${archiveState === 'loading' ? '불러오는 중' : '이전 기록까지 찾기'}</button><//>`}</p>`}
 <//>`;
}

if (window.PS_MOUNT) window.PS_MOUNT(Board); else render(html`<${Board} />`, document.getElementById('app'));
